    ("nested_in_one_function", (x::Int64) -> (try; (try; throw(ArgumentError("o")); catch; (try; x > 0 && throw(DomainError(x)); catch; end); rethrow(); end); Int64(0); catch e; _sm_xs_kind(e); end), Int64(1)),
