    ("int8_slot", (n::Int64) -> (v = Any[n, 2.5]; _sm_s8(Int8(n), v[1]) + _sm_s8(Int8(n), v[2])), Int64(3)),
    ("enum_slot", (n::Int64) -> (v = Any[n, 2.5]; _sm_se(_sm_green, v[1]) + _sm_se(_sm_red, v[2])), Int64(3)),
])
