    ("mutable_callable_captured", (n::Int64) -> (m = _SmMC(n); _sm_mkmc(m) === _sm_mkmc(m) ? 1 : 2), Int64(3)),
    ("mutable_callable_field_write", (n::Int64) -> (m = _sm_newmc(n); m.n += 1; m(1)), Int64(3)),
