function _dl_short_circuit()
    local t = Ref(Int64(0))
    local f = Ref(Int64(0))
    local tf = () -> (t[] += 1; true)
    local ff = () -> (f[] += 1; false)
    local s = Tuple{Int64,Int64}[]
    tf() && tf(); push!(s, (t[], f[])); t[] = f[] = 0
    ff() && tf(); push!(s, (t[], f[])); t[] = f[] = 0
    tf() && ff(); push!(s, (t[], f[])); t[] = f[] = 0
    ff() || ff(); push!(s, (t[], f[]))
    return s
end
