# try_catch: continue to labeled cases, one continue leaving a try block, the last case throwing
function _sw_tc_test(x::Int64, log::Vector{String})
    x == 0 && @goto c0
    x == 1 && @goto c1
    x == 5 && @goto c5
    x == 6 && @goto c6
    @goto done
    @label c0
    push!(log, "_0")
    @goto c5
    @label c1
    try
        push!(log, "bunny")
        @goto c6
    catch e
    end
    @goto done
    @label c5
    push!(log, "_5")
    @goto c6
    @label c6
    push!(log, "_6")
    throw(Int64(555))
    @label done
    return nothing
end
