    e = _ClTaC{Int64}(Type[])
    _cl_ta_cfoo(e, Real)
    return _dw_facts(length(a.args) == 6, a.args[1] === Int64, a.args[2] === Vector{Int64}, a.args[3] === Real,
                    a.args[4] === AbstractVector, a.args[5] === Float64, a.args[6] === _ClTaMyIterable,
                    length(e.args) == n, e.args[1] === Dict{Real,Int64})
