# catch_liveness: a local assigned after a throwing call keeps its old value in catch and after
_ex_cl_foo(n::Int64) = n
_ex_cl_throw(t::Int64) = throw(t == 1 ? "x" : string(t))
function _ex_catch_liveness(n::Int64)
    x = Int64(10)
    e2 = nothing
    incatch = false
    try
        t = _ex_cl_foo(n)
        t > 0 && _ex_cl_throw(t)
        x = 3 + t
    catch e
        incatch = x == 10
        e2 = e
    end
    return _dw_facts(incatch, x == 10, e2 isa String && e2 == "x")
end
# code_after_try_is_executed: code after a try/catch runs; a later throw escapes
function _ex_cat(b::Bool)
    exception = nothing
    try
        throw("foo")
    catch ex
        ex isa String || rethrow()
        exception = ex
    end
    ok = exception isa String
    b && throw("foo")
    return ok
end
# exception: on String catch twice, then a TypeError picked out of on String / on TypeError / catch
_ex_ex_cast(v::Union{Nothing,String}) = v::String
function _ex_exception(n::Int64)
    i = Int64(0)
    try
        throw("Hello")
    catch s
        s isa String ? (i += 10) : rethrow()
    end
    try
        throw("bye")
    catch s
        s isa String ? (i += 10) : rethrow()
    end
    correct = false
    try
        throw(_ex_ex_cast(n > 0 ? nothing : "s"))
    catch e
        if e isa String
            correct = false
        elseif e isa TypeError
            correct = true
        else
            correct = false
        end
    end
    return _dw_facts(i == 20, correct)
end
# finally: a field updated in try is seen by finally
function _ex_finally_foo(a::_ExCell)
    executed = false
    seen = Int64(0)
    if a.i == 42
        try
            a.i = 12
        finally
            seen = a.i
            executed = true
        end
    end
    return _dw_facts(seen == 12, executed)
end
# finally1..finally6 record the order of their steps in a Vector{Int64}: a try body pushes the value
# it sets, each finally pushes the amount it adds, and dead code pushes its own amount
# finally1: return in try; the finally updates the field after the value is taken
function _ex_finally1_f1(h::_ExCell, ord::Vector{Int64})
    try
        j = _ex_func()
        h.i = 1
        push!(ord, 1)
        return h.i
    finally
        push!(ord, 800)
        h.i = h.i + 800
    end
    push!(ord, 200)
    return h.i + 200
end
# finally2: return through two nested finally blocks
function _ex_finally2_f1(h::_ExCell, ord::Vector{Int64})
    try
        j = _ex_func()
        try
            h.i = 1
            push!(ord, 1)
            return h.i
        finally
            push!(ord, 400)
            h.i = h.i + 400
        end
        h.i = 2
        push!(ord, 2)
        return h.i
    finally
        push!(ord, 800)
        h.i = h.i + 800
    end
    push!(ord, 200)
    return h.i + 200
end
# finally3: continue of an outer loop out of two nested try/finally (a flag; Julia's continue is
# innermost), then a return through a finally
function _ex_finally3_f1(h::_ExCell, ord::Vector{Int64})
    try
        try
            j = _ex_func()
            while h.i <= 0
                if h.i == 0
                    try
                        h.i = 1
                        push!(ord, 1)
                        _ex_func()
                        try
                            j2 = _ex_func()
                            cont = false
                            while j2 < 50
                                j2 += _ex_func()
                                if j2 > 30
                                    cont = true
                                    break
                                end
                            end
                            cont || (push!(ord, 200000); h.i = 200000)
                        finally
                            push!(ord, 200)
                            h.i = h.i + 200
                        end
                    finally
                        push!(ord, 400)
                        h.i = h.i + 400
                    end
                end
            end
        finally
            push!(ord, 800)
            h.i = h.i + 800
        end
        return h.i
    finally
        push!(ord, 1600)
        h.i = h.i + 1600
    end
    push!(ord, 2000000)
    h.i = h.i + 2000000
    return Int64(1)
end
# finally4: a return after a try/finally; a later try/finally never runs
function _ex_finally4_f1(h::_ExCell, ord::Vector{Int64})
    try
        j = _ex_func()
        h.i = 1
        push!(ord, 1)
    finally
        push!(ord, 10)
        h.i = h.i + 10
    end
    return h.i + 200
    try
        j = _ex_func()
    finally
        push!(ord, -10)
        h.i = h.i + 10
    end
end
# finally5: returns through nested finally blocks on two paths chosen by a parameter
function _ex_finally5_f1(h::_ExCell, param::Int64, ord::Vector{Int64})
    if param == 0
        try
            j = _ex_func()
            try
                h.i = 1
                push!(ord, 1)
                return h.i
            finally
                push!(ord, 400)
                h.i = h.i + 400
            end
            h.i = 2
            push!(ord, 2)
            return h.i
        finally
            push!(ord, 800)
            h.i = h.i + 800
        end
        push!(ord, -200)
        return h.i + 200
    end
    try
        j = _ex_func()
        try
            h.i = 4
            push!(ord, 4)
            return h.i
        finally
            push!(ord, 100)
            h.i = h.i + 100
        end
        h.i = 2
        push!(ord, 2)
        return h.i
    finally
        push!(ord, 200)
        h.i = h.i + 200
    end
    push!(ord, -200)
    return h.i + 200
end
