_op_mul1double(x) = 1.0 * x
_op_mul0double(x) = 0.0 * x
_op_add0double(x) = 0.0 + x
_op_mul1int(x) = 1 * x
_op_mul0int(x) = 0 * x
_op_add0int(x) = 0 + x
_op_and0(x) = 0 & x
_op_or0(x) = 0 | x
_op_xor0(x) = xor(0, x)
_op_and1(x) = (-1) & x
