              _op_add0double(i) == Float64(i), _op_mul1int(i) == i, _op_add0int(i) == i, _op_mul0int(i) == 0,
              _op_and0(i) == 0, _op_and1(i) == i, _op_or0(i) == i, _op_xor0(i) == i)
    end
    return r
end
