    smi = (a + b, a - b, a * b, div(a, b), a / b, 10n / 5n, mod(a, b), rem(a, b))
    smi_dbl = (a + c, a - c, a * c, div(a, c), a / c, mod(a, c), rem(a, c))
    dbl_smi = (d + b, d - b, d * b, div(d, b), d / b, mod(d, b), rem(d, b))
    dbl_dbl = (d + c, d - c, d * c, div(d, c), d / c, mod(d, c), rem(d, c))
