    aq = n == 1 ? nothing : a
    btrue = n == 1
    return _dw_facts(_ca_try(() -> _ca_ite_m(c)()), _ca_try(() -> (btrue ? c : a)()), _ca_try(() -> (!btrue ? a : c)()),
                     _ca_try(() -> something(c, a)()), _ca_try(() -> something(aq, c)()), _ca_try(() -> (!btrue ? c : a)()),
