struct _CaOpE end
function (::_CaOpE)(str::String; count::Int64 = Int64(1))
    buffer = ""
    for i in 0:count-1
        buffer *= str
        if i < count - 1
            buffer *= ":"
        end
    end
    return buffer
end
function _ca_op(n::Int64)
    a1 = n == 1 ? _CaOpA1() : _CaOpB()
