    d = n == 1 ? _CaOpD() : _CaOpA1()
    e = _CaOpE()
    s = n == 1 ? "foo" : "bar"
    return _dw_facts(a1(), a2(), b(), c(6n), d(), _CaOpD()(n), _CaOpD()(2n), e(s) == "foo", e(s; count = 2n) == "foo:foo",
                     e(s; count = 3n) == "foo:foo:foo", (n == 1 ? a1 : string) isa Function, (n == 1 ? e : string) isa Function)
end

