function _fn_lf_h(n::Int64)
    function k(n::Int64)
        local i::Int64 = 0
        capi = () -> (() -> i)
        capj = (j::Int64) -> (() -> j)
        a = Vector{typeof(capi())}(undef, n)
        b = Vector{typeof(capj(Int64(0)))}(undef, n)
        while i < n
            j = i
            a[i + 1] = capi()
            b[i + 1] = capj(j)
            i += 1
        end
        a_sum = Int64(0); b_sum = Int64(0)
        for m in 1:n
            a_sum += a[m]()
            b_sum += b[m]()
        end
        return a_sum + b_sum
    end
    return k(n)
end
function _fn_lf_h2(n::Int64)
    function k(n::Int64)
