function _fn_lf_nesting(n::Int64)
    mk = (vi::Int64, vj::Int64) -> (() -> vi * n + vj)
    a = Vector{typeof(mk(Int64(0), Int64(0)))}(undef, n * n)
    function f0()
        for i in 0:(n - 1)
            vi = i
            function f1()
                for j in 0:(n - 1)
                    vj = j
                    a[i * n + j + 1] = mk(vi, vj)
                end
            end
            f1()
        end
    end
    f0()
    ok = true
    result = Int64(0)
    for k in 0:(n * n - 1)
