        e2 = try; _pa_cl_m(bar; a = "a", b = "b", c = "c"); Int64(0); catch e; e isa MethodError ? Int64(-1) : Int64(-2); end;
        _dw_facts(r1 == "Foo a b c", r2 == "Bar z a\$b c", e1, e2)), Int64(1)),
